func runSetupFlow(ctx context.Context, w io.Writer, opts EnableOptions) error {
	// If external agents already enabled (via flag or prior config), discover first so they appear in the list.
	if opts.ExternalAgents != nil && *opts.ExternalAgents {
		external.DiscoverAndRegister(ctx)
	}

	agents, externalSelected, err := detectOrSelectAgent(ctx, w, nil, opts.ExternalAgents != nil && *opts.ExternalAgents)
	if err != nil {
		return fmt.Errorf("agent selection failed: %w", err)
	}

	// Set external agents preference based on selection.
	if opts.ExternalAgents == nil {
		opts.ExternalAgents = &externalSelected
	}

	// If external agents newly selected (not pre-discovered), discover and install hooks now.
	if externalSelected && (opts.ExternalAgents == nil || !*opts.ExternalAgents) {
		opts.ExternalAgents = &externalSelected
	}
	if externalSelected {
		external.DiscoverAndRegister(ctx)
		// Install hooks for any newly discovered external agents.
		for _, name := range agent.List() {
			ag, err := agent.Get(name)
			if err != nil {
				continue
			}
			if !ag.IsExternal() {
				continue
			}
			// Check if already in selected list.
			alreadySelected := false
			for _, sel := range agents {
				if sel.Name() == name {
					alreadySelected = true
					break
				}
			}
			if !alreadySelected {
				agents = append(agents, ag)
			}
		}
	}

	return runEnableInteractive(ctx, w, agents, opts)
}

