120→// runAddAgents shows which agents are currently enabled and lets the user add more.
121→// Already-installed agents cannot be deselected.
122→func runAddAgents(ctx context.Context, w io.Writer, opts EnableOptions) error {
123→	// Discover external agent plugins.
124→	external.DiscoverAndRegister(ctx)
125→
126→	installedNames := GetAgentsWithHooksInstalled(ctx)
127→
128→	// Show currently installed agents
129→	if len(installedNames) > 0 {
130→		displayNames := make([]string, 0, len(installedNames))
131→		for _, name := range installedNames {
132→			if ag, err := agent.Get(name); err == nil {
133→				displayNames = append(displayNames, string(ag.Type()))
134→			}
135→		}
136→		fmt.Fprintf(w, "Enabled agents: %s\n\n", strings.Join(displayNames, ", "))
137→	}
138→
139→	// Build pre-selection set from installed agents
140→	installedSet := make(map[types.AgentName]struct{}, len(installedNames))
141→	for _, name := range installedNames {
142→		installedSet[name] = struct{}{}
143→	}
144→
145→	// Check if we can prompt interactively
146→	if !canPromptInteractively() {
147→		fmt.Fprintln(w, "Cannot show agent selection in non-interactive mode.")
148→		fmt.Fprintln(w, "Use: entire configure --agent <name>")
149→		return nil
150→	}
151→
152→	// Build options from registered agents
153→	agentNames := agent.List()
154→	options := make([]huh.Option[string], 0, len(agentNames))
155→	for _, name := range agentNames {
156→		ag, err := agent.Get(name)
157→		if err != nil {
158→			continue
159→		}
160→		if _, ok := agent.AsHookSupport(ag); !ok {
161→			continue
162→		}
163→		if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
164→			continue
165→		}
166→		opt := huh.NewOption(string(ag.Type()), string(name))
167→		if _, installed := installedSet[name]; installed {
168→			opt = opt.Selected(true)
169→		}
170→		options = append(options, opt)
171→	}
172→
173→	if len(options) == 0 {
174→		return errors.New("no agents with hook support available")
175→	}
176→
177→	// Check if all agents are already installed
178→	allInstalled := true
179→	for _, name := range agentNames {
180→		ag, err := agent.Get(name)
181→		if err != nil {
182→			continue
183→		}
184→		if _, ok := agent.AsHookSupport(ag); !ok {
185→			continue
186→		}
187→		if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
188→			continue
189→		}
190→		if _, installed := installedSet[name]; !installed {
191→			allInstalled = false
192→			break
193→		}
194→	}
195→	if allInstalled {
196→		fmt.Fprintln(w, "All available agents are already enabled.")
197→		return nil
198→	}
199→
200→	var selectedAgentNames []string
201→	form := NewAccessibleForm(
202→		huh.NewGroup(
203→			huh.NewMultiSelect[string]().
204→				Title("Enable more agents").
205→				Description("Use space to select, enter to confirm.").
206→				Options(options...).
207→				Validate(func(selected []string) error {
208→					if len(selected) == 0 {
209→						return errors.New("please select at least one agent")
210→					}
211→					// Ensure previously installed agents are still selected
212→					selectedSet := make(map[string]struct{}, len(selected))
213→					for _, s := range selected {
214→						selectedSet[s] = struct{}{}
215→					}
216→					for _, name := range installedNames {
217→						if _, ok := selectedSet[string(name)]; !ok {
218→							ag, err := agent.Get(name)
219→							if err != nil {
220→								continue
221→							}
222→							return fmt.Errorf("cannot remove %s — use `entire configure --remove %s` to remove it", ag.Type(), name)
223→						}
224→					}
225→					return nil
226→				}).
227→				Value(&selectedAgentNames),
